import Root from "./3Escape Hatches/0ReferenceValuewithRef"
import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useRef } from "react"
import { useState } from "react"  

export default function() {
  const refVal = useRef(0)
  return <>
  {refVal.current} <br/>
  <button
  onClick={() => {
    refVal.current = refVal.current + 1
    alert(refVal.current)
  }}
  >increase</button>
  </>
}

function Counting() {
  const [num, setNum] = useState(0)
  function handleCounting() {
    const ref = setInterval(() => {setNum(num+1)})
  }
  return <>
  <h1>{num}</h1>
  <button
  onClick={() => {ref = setInterval(() => {setNum(num+1)})}}
  >play</button> 
  <button
  onClick={() => {clearInterval(ref.curr)}}
  >stop</button>
  </>
}

